extern "C" {int WebPGetInfo(const uint8_t*,size_t,int*,int*);uint8_t* WebPDecodeRGB(const uint8_t*,size_t,int*,int*);void WebPFree(void*);}
using Box=std::array<int,4>;using Color=std::array<uint8_t,3>;
inline int jpeg_orientation(const std::string& raw){const auto*d=reinterpret_cast<const uint8_t*>(raw.data());size_t n=raw.size();if(n<4||d[0]!=255||d[1]!=216)return 1;for(size_t pos=2;pos+4<=n;){if(d[pos++]!=255)break;while(pos<n&&d[pos]==255)++pos;if(pos>=n)break;int marker=d[pos++];if(marker==0xda||marker==0xd9)break;if(marker==0x01||(marker>=0xd0&&marker<=0xd7))continue;if(pos+2>n)break;size_t len=(size_t(d[pos])<<8)|d[pos+1];if(len<2||pos+len>n)break;if(marker==0xe1&&len>=16&&std::memcmp(d+pos+2,"Exif\0\0",6)==0){const auto*t=d+pos+8;size_t size=len-8;bool le=t[0]=='I'&&t[1]=='I',be=t[0]=='M'&&t[1]=='M';if(!le&&!be)return 1;auto u16=[&](size_t p)->uint32_t{return p+2<=size?(le?(uint32_t(t[p])|(uint32_t(t[p+1])<<8)):((uint32_t(t[p])<<8)|t[p+1])):0;};auto u32=[&](size_t p)->uint32_t{return p+4<=size?(le?(uint32_t(t[p])|(uint32_t(t[p+1])<<8)|(uint32_t(t[p+2])<<16)|(uint32_t(t[p+3])<<24)):((uint32_t(t[p])<<24)|(uint32_t(t[p+1])<<16)|(uint32_t(t[p+2])<<8)|t[p+3])):0;};if(u16(2)!=42)return 1;size_t offset=u32(4);if(offset+2>size)return 1;size_t count=u16(offset);for(size_t k=0;k<std::min(count,size_t(256));++k){size_t e=offset+2+k*12;if(e+12>size)break;if(u16(e)==0x112&&u16(e+2)==3&&u32(e+4)==1){int v=u16(e+8);return v>=1&&v<=8?v:1;}}return 1;}pos+=len;}return 1;}
inline void orient_image(PageImage& im,int orientation){if(orientation<=1||orientation>8)return;int w=im.width,h=im.height,nw=orientation>=5?h:w,nh=orientation>=5?w:h;std::vector<uint8_t> rgb(im.rgb.size());for(int y=0;y<h;++y)for(int x=0;x<w;++x){int dx=x,dy=y;switch(orientation){case 2:dx=w-1-x;break;case 3:dx=w-1-x;dy=h-1-y;break;case 4:dy=h-1-y;break;case 5:dx=y;dy=x;break;case 6:dx=h-1-y;dy=x;break;case 7:dx=h-1-y;dy=w-1-x;break;case 8:dx=y;dy=w-1-x;break;}for(int c=0;c<3;++c)rgb[(size_t(dy)*nw+dx)*3+c]=im.rgb[(size_t(y)*w+x)*3+c];}im.width=nw;im.height=nh;im.rgb=std::move(rgb);}
inline PageImage decode_upload(const std::string& raw){require(!raw.empty()&&raw.size()<=24*1024*1024,"Image exceeds 24 MiB or is empty");int w=0,h=0,c=0;const auto* bytes=reinterpret_cast<const uint8_t*>(raw.data());bool webp=raw.size()>12&&raw.compare(0,4,"RIFF")==0&&raw.compare(8,4,"WEBP")==0;bool valid=webp?WebPGetInfo(bytes,raw.size(),&w,&h):stbi_info_from_memory(bytes,raw.size(),&w,&h,&c);require(valid&&w>0&&h>0&&int64_t(w)*h<=40000000,"Invalid image or image exceeds 40 megapixels");uint8_t* ptr=webp?WebPDecodeRGB(bytes,raw.size(),&w,&h):stbi_load_from_memory(bytes,raw.size(),&w,&h,&c,3);require(ptr,"Image decoding failed");PageImage im{w,h,std::vector<uint8_t>(ptr,ptr+size_t(w)*h*3)};if(webp)WebPFree(ptr);else stbi_image_free(ptr);orient_image(im,jpeg_orientation(raw));return im;}
inline void write_png(const fs::path& path,int w,int h,int channels,const uint8_t* data){std::ofstream f(path,std::ios::binary);require(bool(f),"Cannot create image");auto callback=[](void* context,void* data,int n){static_cast<std::ofstream*>(context)->write(static_cast<const char*>(data),n);};require(stbi_write_png_to_func(callback,&f,w,h,channels,data,w*channels)!=0&&bool(f),"Cannot encode PNG");}
inline std::vector<uint8_t> grayscale(const PageImage& im){std::vector<uint8_t> g(size_t(im.width)*im.height);for(size_t i=0;i<g.size();++i)g[i]=(4899*im.rgb[i*3]+9617*im.rgb[i*3+1]+1868*im.rgb[i*3+2]+8192)>>14;return g;}
inline Box expand_box(Box b,int p,int w,int h){return {std::max(0,b[0]-p),std::max(0,b[1]-p),std::min(w,b[2]+p),std::min(h,b[3]+p)};}
inline double gray_fraction(const std::vector<uint8_t>& g,int w,Box b,int threshold,bool above){size_t count=0,n=0;for(int y=b[1];y<b[3];++y)for(int x=b[0];x<b[2];++x){++n;count+=above?(g[size_t(y)*w+x]>threshold):(g[size_t(y)*w+x]<threshold);}return n?double(count)/n:0;}
inline bool paper_white(const std::vector<uint8_t>& g,int w,int h,Box b,bool invert){int pad=std::clamp(int(std::nearbyint(std::min(b[2]-b[0],b[3]-b[1])*.12)),5,12);auto a=expand_box(b,pad,w,h);size_t ring=0,white=0,inside=0,bright=0;for(int y=a[1];y<a[3];++y)for(int x=a[0];x<a[2];++x){int v=g[size_t(y)*w+x];if(invert)v=255-v;if(x>=b[0]&&x<b[2]&&y>=b[1]&&y<b[3]){++inside;bright+=v>=230;}else{++ring;white+=v>=240;}}return ring>=20&&double(white)/ring>=.98&&inside&&double(bright)/inside>=.5;}
inline bool tight_white_surround(const std::vector<uint8_t>& g,int w,int h,Box b){auto outer=expand_box(b,3,w,h);size_t n=0,white=0;for(int y=outer[1];y<outer[3];++y)for(int x=outer[0];x<outer[2];++x)if(x<b[0]||x>=b[2]||y<b[1]||y>=b[3]){++n;white+=g[size_t(y)*w+x]>=240;}return n>=20&&double(white)/n>=.995&&gray_fraction(g,w,b,229,true)>=.60;}
inline int paper_background(const std::vector<uint8_t>& g,int w,int h,Box b){if(paper_white(g,w,h,b,false)||tight_white_surround(g,w,h,b))return 255;if(paper_white(g,w,h,b,true))return 0;int dim=std::min(b[2]-b[0],b[3]-b[1]);if(dim<20)return -1;int inset=std::clamp(dim/12,3,12);Box inner{b[0]+inset,b[1]+inset,b[2]-inset,b[3]-inset};size_t n=0,dark=0;for(int y=inner[1];y<inner[3];++y)for(int x=inner[0];x<inner[2];++x){int weight=(y<inner[1]+2)+(y>=inner[3]-2)+(x<inner[0]+2)+(x>=inner[2]-2);n+=weight;dark+=weight*(g[size_t(y)*w+x]<25);}return n&&double(dark)/n>.985&&gray_fraction(g,w,inner,40,false)>.70?0:-1;}
inline bool dark_surround(const std::vector<uint8_t>& g,int w,int h,Box b){auto a=expand_box(b,std::clamp((b[3]-b[1])/3,8,40),w,h);size_t n=0,d=0;for(int y=a[1];y<a[3];++y)for(int x=a[0];x<a[2];++x)if(x<b[0]||x>=b[2]||y<b[1]||y>=b[3]){++n;d+=g[size_t(y)*w+x]<80;}return n&&double(d)/n>.65;}
inline Color median_color(const PageImage& im,Box b,const std::function<bool(int,int)>& accept){std::array<std::array<size_t,256>,3> hist{};size_t n=0;for(int y=b[1];y<b[3];++y)for(int x=b[0];x<b[2];++x)if(accept(x,y)){++n;for(int c=0;c<3;++c)++hist[c][im.rgb[(size_t(y)*im.width+x)*3+c]];}Color out{255,255,255};if(!n)return out;for(int c=0;c<3;++c){size_t sum=0;int lo=-1,hi=255;for(int v=0;v<256;++v){sum+=hist[c][v];if(lo<0&&sum>(n-1)/2)lo=v;if(sum>n/2){hi=v;break;}}out[c]=uint8_t(std::nearbyint((lo+hi)/2.));}return out;}
struct FlatColors{bool valid=false;Color background{255,255,255},ink{17,17,17};};
inline int color_distance(const PageImage& im,int x,int y,Color c){size_t i=(size_t(y)*im.width+x)*3;return std::max({std::abs(int(im.rgb[i])-c[0]),std::abs(int(im.rgb[i+1])-c[1]),std::abs(int(im.rgb[i+2])-c[2])});}
inline FlatColors flat_colors(const PageImage& im,Box b){int pad=std::clamp(int(std::nearbyint(std::min(b[2]-b[0],b[3]-b[1])*.12)),5,12);auto a=expand_box(b,pad,im.width,im.height);auto ring=[&](int x,int y){return x<b[0]||x>=b[2]||y<b[1]||y>=b[3];};Color bg=median_color(im,a,ring);size_t n=0,same=0;for(int y=a[1];y<a[3];++y)for(int x=a[0];x<a[2];++x)if(ring(x,y)){++n;same+=color_distance(im,x,y,bg)<16;}if(n<20||double(same)/n<.97)return {};n=0;same=0;size_t ink=0;for(int y=b[1];y<b[3];++y)for(int x=b[0];x<b[2];++x){++n;auto d=color_distance(im,x,y,bg);same+=d<22;ink+=d>55;}if(!n||double(same)/n<.45||ink<3)return {};return {true,bg,median_color(im,b,[&](int x,int y){return color_distance(im,x,y,bg)>55;})};}
inline Box tighten_dark_text(const std::vector<uint8_t>& g,int w,int h,Box b){if(paper_background(g,w,h,b)!=0||gray_fraction(g,w,b,160,true)>.12)return b;int bw=b[2]-b[0],bh=b[3]-b[1];std::vector<uint8_t> seen(size_t(bw)*bh);Box keep{bw,bh,0,0};bool found=false;std::vector<int> queue;
for(int y=0;y<bh;++y)for(int x=0;x<bw;++x){int pos=y*bw+x;if(seen[pos]||g[size_t(y+b[1])*w+x+b[0]]<=160)continue;queue.clear();queue.push_back(pos);seen[pos]=1;Box cc{x,y,x+1,y+1};for(size_t i=0;i<queue.size();++i){int px=queue[i]%bw,py=queue[i]/bw;cc[0]=std::min(cc[0],px);cc[1]=std::min(cc[1],py);cc[2]=std::max(cc[2],px+1);cc[3]=std::max(cc[3],py+1);for(int dy=-1;dy<=1;++dy)for(int dx=-1;dx<=1;++dx){int nx=px+dx,ny=py+dy;if(nx<0||nx>=bw||ny<0||ny>=bh)continue;int np=ny*bw+nx;if(!seen[np]&&g[size_t(ny+b[1])*w+nx+b[0]]>160){seen[np]=1;queue.push_back(np);}}}if(queue.size()<3||queue.size()>size_t(bw)*bh*.15||cc[0]<=1||cc[1]<=1||cc[2]>=bw-1||cc[3]>=bh-1)continue;found=true;keep={std::min(keep[0],cc[0]),std::min(keep[1],cc[1]),std::max(keep[2],cc[2]),std::max(keep[3],cc[3])};}if(!found)return b;return {std::max(b[0],b[0]+keep[0]-3),std::max(b[1],b[1]+keep[1]-3),std::min(b[2],b[0]+keep[2]+3),std::min(b[3],b[1]+keep[3]+3)};}
inline bool eroded_mask_pixel(const Region& bubble,int x,int y,int w,int h){int side=bubble.mask_side;int sx1=std::clamp((x-3)*side/w,0,side-1),sy1=std::clamp((y-3)*side/h,0,side-1),sx2=std::clamp((x+3)*side/w,0,side-1),sy2=std::clamp((y+3)*side/h,0,side-1);for(int sy=sy1;sy<=sy2;++sy)for(int sx=sx1;sx<=sx2;++sx)if(!bubble.mask[sy*side+sx])return false;return true;}
inline double mask_coverage(const Region& bubble,Box box,int w,int h){int side=bubble.mask_side;int x1=std::clamp(box[0]*side/w,0,side-1),y1=std::clamp(box[1]*side/h,0,side-1),x2=std::clamp(std::max(x1+1,box[2]*side/w),1,side),y2=std::clamp(std::max(y1+1,box[3]*side/h),1,side);size_t n=0,c=0;for(int y=y1;y<y2;++y)for(int x=x1;x<x2;++x){++n;c+=bubble.mask[y*side+x]>0;}return n?double(c)/n:0;}
inline std::string hex_color(Color c){std::ostringstream o;o<<'#'<<std::hex<<std::setfill('0');for(auto v:c)o<<std::setw(2)<<int(v);return o.str();}
inline void crop_ppm(const fs::path& path,const PageImage& im,Box b){std::ofstream f(path,std::ios::binary);f<<"P6\n"<<b[2]-b[0]<<' '<<b[3]-b[1]<<"\n255\n";for(int y=b[1];y<b[3];++y)f.write(reinterpret_cast<const char*>(im.rgb.data()+(size_t(y)*im.width+b[0])*3),(b[2]-b[0])*3);require(bool(f),"Cannot write OCR crop");}
